def _remove_stale_chat_files(self, chat: Chat, moved: bool = False) -> int:
    """
    Delete every file that carries ``chat.id`` except ``chat.file_path``.

    A card has ONE file (``<board>/<column>/<slug>.<id>.json``). The old
    cleanup removed only ``current_chat.file_path``, so when two files for
    one id already existed (a move done by another process, a hand-edited
    card) the stale copy survived; the next write loaded that stale copy and
    reverted the fields the caller had just changed.

    The tree scan only runs when the card is being written to a NEW path, or
    when the index still resolves the id to another path, so the common
    save (same path, no duplicate) stays O(1).

    :param chat: The chat being saved; ``id`` and ``file_path`` are used.
    :param moved: True when the card is being written to a new path.
    :return: Number of stale files removed.
    """
    if not chat.id or not chat.file_path:
        return 0

    indexed_path = None
    if not moved:
        store = self._chat_index_store()
        if store is not None:
            try:
                indexed_path = store.find_path(str(chat.id))
            except Exception:  # pragma: no cover - defensive
                indexed_path = None
        if not indexed_path or indexed_path == chat.file_path:
            return 0

    removed = 0
    suffixes = (f".{chat.id}.json", f".{chat.id}.yaml")
    for other_path in self.chat_paths():
        if other_path == chat.file_path:
            continue
        if "/.archive/" in other_path.replace(os.sep, "/"):
            continue
        if not os.path.basename(other_path).endswith(suffixes):
            continue
        logger.info(
            "Save chat: removing duplicate %s for chat %s", other_path, chat.id
        )
        if os.path.isfile(other_path):
            os.remove(other_path)
            removed += 1

    if removed:
        self._mark_index_dirty_if_building()
    return removed

